                    continue
                rr, cc = r + dr, c + dc
                while 0 <= rr < h and 0 <= cc < w:
                    if grid[rr][cc] == 2:
                        break
                    # only fill gaps bracketed by markers on this diagonal
                    rr += dr
                    cc += dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 2:
                    rr, cc = r + dr, c + dc
                    while (rr, cc) != (r + (rr-r), c + (cc-c)):  # unused safety
